<template><view class="wholesale-ui wh-body"><FeaturePageState :status="status" :error="error" mode="skeleton" skeleton-variant="list" @retry="load"/><template v-if="status==='ready'"><EmptyState v-if="!visibleItems.length" :text="`暂无${activeRoleLabel}兑换记录`"/><view v-for="item in visibleItems" :key="item.id" class="wh-card withdrawal-card"><view class="wh-row"><view><view class="wh-blue withdrawal-amount">{{points(item.points)}}</view><text class="withdrawal-yuan">约 ¥{{money(item.amountYuan)}}</text><text class="withdrawal-meta">单号 {{redemptionNoOf(item)}} · {{withdrawalIdentityOf(item).identityLabel}}积分<template v-if="withdrawalIdentityOf(item).identityScopeLabel"> · {{withdrawalIdentityOf(item).identityScopeLabel}}</template></text></view><view class="withdrawal-state"><text class="wh-tag">{{withdrawalIdentityOf(item).identityLabel}}</text><text class="wh-badge-status" :class="`status-${item.status}`">{{statusLabel(item.status)}}</text></view></view><view class="wh-datum"><view><text class="wh-muted">申请时间</text><text>{{businessDateLabel(item.createdAt)}}</text></view><view v-if="item.reviewedAt"><text class="wh-muted">审核时间</text><text>{{businessDateLabel(item.reviewedAt)}}</text></view><view v-if="item.settledAt"><text class="wh-muted">到账时间</text><text>{{businessDateLabel(item.settledAt)}}</text></view><view><text class="wh-muted">审核状态</text><text>{{statusLabel(item.status)}}</text></view><view v-if="item.rejectReason"><text class="wh-muted">驳回原因</text><text class="withdrawal-reason">{{item.rejectReason}}</text></view></view></view><button v-if="hasMore" class="wh-secondary wh-pill" :disabled="loadingMore" @click="more">{{loadingMore?'加载中…':'加载更多'}}</button><text v-if="moreError" class="wh-error">{{moreError}}</text></template></view></template>
<script setup>
import {ref,watch,computed,onUnmounted} from 'vue'
import {money} from '../features/exclusive/format'
import {businessDateLabel} from '../features/business/format'
import {getBusinessContext,getBusinessWithdrawals} from '../services/business'
import {withdrawalIdentityOf,redemptionNoOf} from '../services/partner-wallet'
import {useAsyncPage} from '../composables/useAsyncPage'
import FeaturePageState from './FeaturePageState.vue'
import EmptyState from './EmptyState.vue'
const props=defineProps({pageQuery:Object}),context=ref(null),items=ref([]),hasMore=ref(false),loadingMore=ref(false),moreError=ref(''),roles=[{value:'partner',label:'合伙人'},{value:'agent',label:'代理'},{value:'costore',label:'合店老板'}];let cursor=null,epoch=0
const {data,status,error,load}=useAsyncPage(async()=>{const ctx=await getBusinessContext(null,props.pageQuery?.contextId);context.value=ctx;return getBusinessWithdrawals(ctx.id)},false)
watch(()=>props.pageQuery,query=>{if(query)load()},{immediate:true});watch(status,value=>{if(value==='loading'){++epoch;loadingMore.value=false;moreError.value=''}});watch(data,result=>{if(result){items.value=result.items;hasMore.value=result.hasMore;cursor=result.nextCursor}})
const statusLabel=value=>({PENDING_REVIEW:'待审核',PROCESSING:'处理中',SUCCEEDED:'已完成',REJECTED:'未通过'}[value]||'状态待确认')
const points=value=>`${money(value)}积分`
const activeRole=computed(()=>({wholesale:'partner',agency:'agent',costore:'costore'}[context.value?.module]||'partner')),visibleItems=computed(()=>items.value.filter(item=>item.identity===activeRole.value)),activeRoleLabel=computed(()=>roles.find(item=>item.value===activeRole.value)?.label||'')
async function more(){if(loadingMore.value||!hasMore.value)return;const current=epoch;loadingMore.value=true;try{const result=await getBusinessWithdrawals(context.value.id,cursor);if(current===epoch){items.value=[...new Map([...items.value,...result.items].map(item=>[item.id,item])).values()];cursor=result.nextCursor;hasMore.value=result.hasMore}}catch(reason){if(current===epoch)moreError.value=reason.message}finally{if(current===epoch)loadingMore.value=false}}
onUnmounted(()=>{++epoch});defineExpose({refresh:load})
</script>
<style>@import '../styles/account.css';@import '../styles/exclusive.css';@import '../styles/business.css';</style>
<style>@import '../styles/wholesale.css';</style>
<style scoped>.withdrawal-card{position:relative;padding:1em .8em;font-size:.85em}.withdrawal-card .wh-badge-status{border-radius:2em;align-self:flex-start}.withdrawal-amount{font-size:1.35em;line-height:1.5}.withdrawal-yuan,.withdrawal-meta{display:block;color:#989eb6;font-size:.82em}.withdrawal-meta{margin-top:.3em}.withdrawal-state{display:flex;flex-direction:column;align-items:flex-end;gap:.45em}.withdrawal-card .wh-datum{margin-top:1.4em;font-size:.95em}.withdrawal-reason{color:#ff9fb3}.status-PENDING_REVIEW{color:#b7c7e4;background:#3c4668}.status-SUCCEEDED{color:#97ca89;background:#24382c}.status-REJECTED{color:#e7a0b4;background:#4a3040}</style>
